package world.phantasmal.webui.widgets

import kotlinx.browser.document
import kotlinx.browser.window
import kotlin.math.min
import kotlin.math.max
import org.w3c.dom.*
import org.w3c.dom.events.Event
import org.w3c.dom.events.KeyboardEvent
import org.w3c.dom.events.MouseEvent
import world.phantasmal.core.disposable.Disposable
import world.phantasmal.core.disposable.disposable
import world.phantasmal.cell.Cell
import world.phantasmal.cell.list.emptyListCell
import world.phantasmal.cell.nullCell
import world.phantasmal.cell.trueCell
import world.phantasmal.webui.dom.disposableListener
import world.phantasmal.webui.dom.div

class Menu<T : Any>(
    visible: Cell<Boolean> = trueCell(),
    enabled: Cell<Boolean> = trueCell(),
    tooltip: Cell<String?> = nullCell(),
    private val items: Cell<List<T>> = emptyListCell(),
    private val itemToString: (T) -> String = Any::toString,
    private val onSelect: (T) -> Unit = {},
    private val onCancel: () -> Unit = {},
) : Widget(
    visible,
    enabled,
    tooltip,
) {
    private lateinit var innerElement: HTMLElement
    private var highlightedIndex: Int? = null
    private var highlightedElement: Element? = null
    private var previouslyFocusedElement: Element? = null
    private var onDocumentMouseDownListener: Disposable? = null

    override fun Node.createElement() =
        div {
            className = "pw-menu"
            tabIndex = -1
            onmouseup = ::onMouseUp
            onkeydown = ::onKeyDown
            onblur = { onBlur() }

            innerElement = div {
                className = "pw-menu-inner"
                onmouseover = ::onInnerMouseOver

                bindChildrenTo(items) { item, index ->
                    div {
                        dataset["index"] = index.toString()
                        textContent = itemToString(item)
                    }
                }
            }

            observeNow(this@Menu.visible) {
                if (it) {
                    onDocumentMouseDownListener =
                        document.disposableListener("mousedown", ::onDocumentMouseDown)
                } else {
                    onDocumentMouseDownListener?.dispose()
                    onDocumentMouseDownListener = null
                    clearHighlightItem()

                    (previouslyFocusedElement as HTMLElement?)?.asDynamic()?.focus(js("({preventScroll: true})"))
                }
            }

            observeNow(enabled) {
                if (!it) {
                    clearHighlightItem()
                }
            }

            observeNow(items) {
                clearHighlightItem()
            }

            addDisposable(document.disposableListener("keydown", ::onDocumentKeyDown))
            // Scrolling the list is allowed; moving its anchor or resizing dismisses the popup.
            val dismiss: (Event) -> Unit = { event ->
                val target = event.target
                if (this@Menu.visible.value && (target !is Node || !this.contains(target))) onCancel()
            }
            document.addEventListener("scroll", dismiss, true)
            addDisposable(disposable { document.removeEventListener("scroll", dismiss, true) })
            addDisposable(window.disposableListener("resize", dismiss))
        }

    override fun dispose() {
        onDocumentMouseDownListener?.dispose()
        super.dispose()
    }

    override fun focus() {
        previouslyFocusedElement = document.activeElement
        element.asDynamic().focus(js("({preventScroll: true})"))
    }

    /** Keep the popup out of the panel's scroll layout and inside the viewport. */
    fun positionAt(anchor: HTMLElement) {
        val bounds = anchor.getBoundingClientRect()
        val margin = 4.0
        val availableWidth = max(0.0, window.innerWidth - 2 * margin)
        element.style.apply {
            position = "fixed"
            left = "${margin}px"
            top = "${margin}px"
            minWidth = "${min(bounds.width, availableWidth)}px"
            maxWidth = "${availableWidth}px"
            width = "max-content"
        }
        val below = max(0.0, window.innerHeight - bounds.bottom - margin)
        val above = max(0.0, bounds.top - margin)
        val openAbove = below < min(500.0, innerElement.scrollHeight.toDouble()) && above > below
        innerElement.style.maxHeight = "${min(500.0, if (openAbove) above - 4 else below - 4).coerceAtLeast(0.0)}px"
        val popup = element.getBoundingClientRect()
        element.style.left = "${bounds.left.coerceIn(margin, max(margin, window.innerWidth - popup.width - margin))}px"
        element.style.top = "${if (openAbove) max(margin, bounds.top - popup.height) else bounds.bottom}px"
    }

    fun highlightItem(item: T) {
        val idx = items.value.indexOf(item)

        if (idx != -1) {
            highlightItemAt(idx)
        }
    }

    fun highlightNext() {
        highlightItemAt(
            when (val idx = highlightedIndex) {
                null, items.value.lastIndex -> 0
                else -> idx + 1
            }
        )
    }

    fun highlightPrev() {
        highlightItemAt(
            when (val idx = highlightedIndex) {
                null, 0 -> items.value.lastIndex
                else -> idx - 1
            }
        )
    }

    fun selectHighlighted() {
        highlightedIndex?.let(::selectItem)
    }

    private fun onMouseUp(e: MouseEvent) {
        val target = e.target

        if (target !is HTMLElement) return

        target.dataset["index"]?.toIntOrNull()?.let(::selectItem)
    }

    private fun onKeyDown(e: KeyboardEvent) {
        when (e.key) {
            "ArrowDown" -> {
                e.preventDefault()
                highlightNext()
            }

            "ArrowUp" -> {
                e.preventDefault()
                highlightPrev()
            }

            "Enter", " " -> {
                e.preventDefault()
                e.stopPropagation()
                selectHighlighted()
            }
        }
    }

    private fun onBlur() {
        onCancel()
    }

    private fun onInnerMouseOver(e: MouseEvent) {
        val target = e.target

        if (target is HTMLElement) {
            target.dataset["index"]?.toIntOrNull()?.let(::highlightItemAt)
        }
    }

    private fun onDocumentMouseDown(e: Event) {
        val target = e.target

        if (target !is Node || !element.contains(target)) {
            onCancel()
        }
    }

    private fun onDocumentKeyDown(e: KeyboardEvent) {
        if (e.key === "Escape") {
            onCancel()
        }
    }

    private fun clearHighlightItem() {
        highlightedElement?.classList?.remove("pw-menu-highlighted")
        highlightedIndex = null
        highlightedElement = null
    }

    private fun highlightItemAt(index: Int) {
        highlightedElement?.classList?.remove("pw-menu-highlighted")

        if (!enabled.value) return

        highlightedElement = innerElement.children.item(index)

        highlightedElement?.let {
            highlightedIndex = index
            it.classList.add("pw-menu-highlighted")
            scrollIntoInnerView(it)
        }
    }

    /**
     * Scrolls only the item list. Element.scrollIntoView would also scroll the menu's scrollable
     * ancestors, which moves an item under the pointer while the button that opened the menu is
     * still pressed, so the mouseup selects that item and closes the menu.
     */
    private fun scrollIntoInnerView(item: Element) {
        val list = innerElement.getBoundingClientRect()
        val rect = item.getBoundingClientRect()

        if (rect.top < list.top) {
            innerElement.scrollTop -= list.top - rect.top
        } else if (rect.bottom > list.bottom) {
            innerElement.scrollTop += rect.bottom - list.bottom
        }
    }

    private fun selectItem(index: Int) {
        if (!enabled.value) return

        items.value.getOrNull(index)?.let(onSelect)
    }

    companion object {
        init {
            @Suppress("CssUnusedSymbol", "CssUnresolvedCustomProperty")
            // language=css
            style("""
                .pw-menu {
                    z-index: 1001;
                    position: absolute;
                    box-sizing: border-box;
                    outline: none;
                    border: var(--pw-control-border);
                    --scrollbar-color: hsl(0, 0%, 18%);
                    --scrollbar-thumb-color: hsl(0, 0%, 22%);
                }

                .pw-menu > .pw-menu-inner {
                    overflow: auto;
                    background-color: var(--pw-control-bg-color);
                    max-height: 500px;
                    border: var(--pw-control-inner-border);
                }

                .pw-menu > .pw-menu-inner > * {
                    padding: 3px 6px;
                    white-space: normal;
                    overflow-wrap: anywhere;
                }

                .pw-menu > .pw-menu-inner > .pw-menu-highlighted {
                    background-color: var(--pw-control-bg-color-hover);
                    color: var(--pw-control-text-color-hover);
                }
            """.trimIndent())
        }
    }
}
